import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:pdf_engine_core/cos.dart';
import 'package:pdf_engine_core/pdf_engine_core.dart';
import 'package:test/test.dart';

/// Shared corpus generated by tool/generate_fixtures.py.
const _fixtureDir = '../fixtures/pdf';

Uint8List _fixture(String name) => File('$_fixtureDir/$name').readAsBytesSync();

Uint8List _ascii(String text) => Uint8List.fromList(latin1.encode(text));

PdfObject _parse(String text) => PdfObjectParser(_ascii(text)).parseObject();

void main() {
  final manifest =
      jsonDecode(File('$_fixtureDir/manifest.json').readAsStringSync())
          as Map<String, Object?>;
  final fixtures = (manifest['fixtures']! as List<Object?>)
      .cast<Map<String, Object?>>();

  group('PdfCosDocument on the fixture corpus', () {
    for (final fixture in fixtures) {
      final file = fixture['file']! as String;
      final expect_ = fixture['expect']! as Map<String, Object?>;
      final pageCount = fixture['pageCount'] as int?;

      if (expect_['isEncrypted'] == true) {
        test('$file is rejected as encrypted', () {
          expect(
            () => PdfCosDocument.open(_fixture(file)),
            throwsA(
              isA<PdfUnsupportedFeatureException>().having(
                (error) => error.feature,
                'feature',
                PdfUnsupportedFeature.encryption,
              ),
            ),
          );
        });
        continue;
      }
      if (expect_['isPdf'] == false) {
        test('$file is rejected as not a PDF', () {
          expect(
            () => PdfCosDocument.open(_fixture(file)),
            throwsA(isA<PdfInvalidDocumentException>()),
          );
        });
        continue;
      }
      if (pageCount == null) {
        test('$file opens or fails with a typed exception', () {
          try {
            final document = PdfCosDocument.open(_fixture(file));
            document.pages;
          } on PdfInvalidDocumentException {
            // Acceptable: too damaged to read.
          }
        });
        continue;
      }

      test('$file opens with $pageCount page(s)', () {
        final document = PdfCosDocument.open(_fixture(file));
        expect(document.pages, hasLength(pageCount));
        for (final page in document.pages) {
          expect(page.width, greaterThan(0));
          expect(page.height, greaterThan(0));
        }
      });

      test('$file survives an incremental update', () {
        final original = _fixture(file);
        final document = PdfCosDocument.open(original);
        final rootRef = document.trailer['Root']! as PdfRef;
        final catalog = document.catalog.copy()
          ..['PageMode'] = const PdfName('UseOutlines');
        final update = PdfIncrementalUpdate(document)
          ..set(rootRef.number, catalog);
        final output = update.build();

        if (!document.wasRepaired) {
          // The original bytes are kept as a prefix.
          expect(output.sublist(0, original.length), original);
        }
        final reopened = PdfCosDocument.open(output);
        expect(reopened.wasRepaired, isFalse);
        expect(reopened.pages, hasLength(pageCount));
        expect(reopened.catalog['PageMode'], const PdfName('UseOutlines'));
        expect(reopened.usesXrefStreams, document.usesXrefStreams);
      });

      test('$file survives a full rewrite', () {
        final document = PdfCosDocument.open(_fixture(file));
        final output = PdfDocumentRewriter.rewrite(document);
        final reopened = PdfCosDocument.open(output);
        expect(reopened.wasRepaired, isFalse);
        expect(reopened.usesXrefStreams, isFalse);
        expect(reopened.pages, hasLength(pageCount));
      });
    }

    test('reads compressed object streams', () {
      final document = PdfCosDocument.open(_fixture('form_object_streams.pdf'));
      expect(document.usesXrefStreams, isTrue);
      expect(document.wasRepaired, isFalse);
      final acroForm = document.resolve(document.catalog['AcroForm']);
      expect(acroForm, isA<PdfDict>());
      final fields = document.resolve((acroForm! as PdfDict)['Fields']);
      expect((fields! as PdfArray).length, 6);
    });

    test('repairs a file whose xref offsets are all wrong', () {
      final document = PdfCosDocument.open(_fixture('broken_xref_offsets.pdf'));
      expect(document.pages, hasLength(1));
    });

    test('reads a file with junk before the header', () {
      final document = PdfCosDocument.open(_fixture('junk_before_header.pdf'));
      expect(document.pages, hasLength(1));
    });

    test('applies inherited page attributes and rotation', () {
      final document = PdfCosDocument.open(_fixture('rotated_pages.pdf'));
      expect(document.pages.map((page) => page.rotate), <int>[0, 90, 180, 270]);
      expect(document.pages.first.resources, isNotNull);
    });

    test('reads mixed page sizes in order', () {
      final document = PdfCosDocument.open(_fixture('mixed_page_sizes.pdf'));
      expect(document.pages.map((page) => page.width.round()), <int>[
        595,
        612,
        842,
        300,
      ]);
    });

    test('decodes Flate content streams', () {
      final document = PdfCosDocument.open(
        _fixture('flate_content_stream.pdf'),
      );
      final contents = document.resolve(document.pages.first.dict['Contents']);
      final text = latin1.decode(document.decodeStream(contents! as PdfStream));
      expect(text, contains('Flate content stream'));
    });

    test('rejects data without a PDF header', () {
      expect(
        () => PdfCosDocument.open(_ascii('hello')),
        throwsA(isA<PdfInvalidDocumentException>()),
      );
    });
  });

  group('PdfIncrementalUpdate', () {
    test('keeps generation numbers and chains /Prev', () {
      final original = _fixture('form_classic.pdf');
      final document = PdfCosDocument.open(original);
      final rootRef = document.trailer['Root']! as PdfRef;
      final output = (PdfIncrementalUpdate(
        document,
      )..set(rootRef.number, document.catalog.copy())).build();
      final tail = latin1.decode(output.sublist(original.length));
      expect(tail, contains('${rootRef.number} ${rootRef.generation} obj'));
      expect(tail, contains('/Prev ${document.lastXrefOffset}'));
      expect(tail, endsWith('%%EOF\n'));
    });

    test('writes an xref stream when the original uses one', () {
      final original = _fixture('form_object_streams.pdf');
      final document = PdfCosDocument.open(original);
      final rootRef = document.trailer['Root']! as PdfRef;
      final output = (PdfIncrementalUpdate(
        document,
      )..set(rootRef.number, document.catalog.copy())).build();
      final tail = latin1.decode(output.sublist(original.length));
      expect(tail, contains('/Type /XRef'));
      expect(tail, isNot(contains('\nxref\n')));
    });

    test('adds new objects after the existing ones', () {
      final document = PdfCosDocument.open(_fixture('text_single_page.pdf'));
      final update = PdfIncrementalUpdate(document);
      final ref = update.add(PdfString.fromText('new'));
      expect(ref.number, document.size);
      final rootRef = document.trailer['Root']! as PdfRef;
      update.set(rootRef.number, document.catalog.copy()..['Extra'] = ref);
      final reopened = PdfCosDocument.open(update.build());
      final extra = reopened.resolve(reopened.catalog['Extra']);
      expect((extra! as PdfString).text, 'new');
    });

    test('returns the original bytes when nothing changed', () {
      final original = _fixture('text_single_page.pdf');
      final document = PdfCosDocument.open(original);
      expect(PdfIncrementalUpdate(document).build(), same(original));
    });
  });

  group('PdfObjectParser', () {
    test('parses names with #xx escapes', () {
      expect(_parse('/A#20B'), const PdfName('A B'));
    });

    test('parses literal string escapes', () {
      // Raw part ends in a backslash; the next literal adds a real newline,
      // so the PDF string contains backslash + end-of-line (a continuation).
      final string =
          _parse(
                r'(a\(b\)\\c\nd\137e\'
                '\nf)',
              )
              as PdfString;
      expect(string.text, 'a(b)\\c\nd_ef');
    });

    test('parses nested parentheses in literal strings', () {
      expect((_parse('(a (b) c)') as PdfString).text, 'a (b) c');
    });

    test('parses hex strings, padding an odd digit', () {
      final string = _parse('<48 65 6C 6C 6F 7>') as PdfString;
      expect(string.bytes, <int>[0x48, 0x65, 0x6C, 0x6C, 0x6F, 0x70]);
      expect(string.isHex, isTrue);
    });

    test('tells references from numbers', () {
      final array = _parse('[1 2 R 3 4 -5 .5 -.25 6.]') as PdfArray;
      expect(array.items, <PdfObject>[
        const PdfRef(1, 2),
        const PdfNumber(3),
        const PdfNumber(4),
        const PdfNumber(-5),
        const PdfNumber(0.5),
        const PdfNumber(-0.25),
        const PdfNumber(6.0),
      ]);
    });

    test('parses dictionaries with comments and nesting', () {
      final dict =
          _parse(
                '<< /Type /Page % comment\n /Kids [ 1 0 R ] /D << /x true >> >>',
              )
              as PdfDict;
      expect(dict['Type'], const PdfName('Page'));
      expect((dict['Kids']! as PdfArray).items.single, const PdfRef(1));
      expect((dict['D']! as PdfDict)['x'], const PdfBool(true));
    });

    test('reads a stream even when /Length is wrong', () {
      final parser = PdfObjectParser(
        _ascii('7 0 obj\n<< /Length 999 >>\nstream\nabc\nendstream\nendobj'),
      );
      final object = parser.parseIndirectObject().object as PdfStream;
      expect(latin1.decode(object.rawData), 'abc');
    });
  });

  group('serialization', () {
    String serialize(PdfObject object) {
      final out = <int>[];
      PdfObjectSerializer.write(object, out);
      return latin1.decode(out);
    }

    test('round-trips strings with special characters', () {
      final original = PdfString.fromText('Line one\nLine (two) \\ end');
      final reparsed = _parse(serialize(original)) as PdfString;
      expect(reparsed.text, original.text);
    });

    test('writes numbers without exponents', () {
      expect(PdfObjectSerializer.formatNumber(0.0000001), '0');
      expect(PdfObjectSerializer.formatNumber(12.5), '12.5');
      expect(PdfObjectSerializer.formatNumber(3.0), '3');
      expect(PdfObjectSerializer.formatNumber(-0.25), '-0.25');
    });

    test('escapes names', () {
      expect(serialize(const PdfName('A B#')), '/A#20B#23');
    });
  });

  group('text strings', () {
    test('uses PDFDocEncoding for Latin text', () {
      final string = PdfString.fromText('Café • €');
      expect(string.bytes.first, 0x43);
      expect(string.bytes.length, 8);
      expect(string.text, 'Café • €');
    });

    test('falls back to UTF-16BE for other scripts', () {
      final string = PdfString.fromText('সাকিব عربي');
      expect(string.bytes.sublist(0, 2), <int>[0xFE, 0xFF]);
      expect(string.text, 'সাকিব عربي');
    });
  });

  group('filters', () {
    test('ASCIIHexDecode', () {
      expect(asciiHexDecode(_ascii('48 65 6c6c 6F>')), _ascii('Hello'));
    });

    test('ASCII85Decode, including the z shortcut', () {
      expect(
        ascii85Decode(_ascii('<~87cURD_*#-6q/;CDfTZ)+T~>')),
        _ascii('Hello, PDF world!'),
      );
      expect(ascii85Decode(_ascii('<~z@:B~>')), <int>[0, 0, 0, 0, 0x61, 0x62]);
    });

    test('LZWDecode matches the example in the PDF specification', () {
      final encoded = Uint8List.fromList(<int>[
        0x80, 0x0B, 0x60, 0x50, 0x22, 0x0C, 0x0C, 0x85, 0x01, //
      ]);
      expect(lzwDecode(encoded), _ascii('-----A---B'));
    });

    test('RunLengthDecode', () {
      final encoded = Uint8List.fromList(<int>[
        2,
        0x61,
        0x62,
        0x63,
        254,
        0x78,
        128,
      ]);
      expect(runLengthDecode(encoded), _ascii('abcxxx'));
    });

    test('PNG Up predictor', () {
      final parms = PdfDict(<String, PdfObject>{
        'Predictor': const PdfNumber(12),
        'Columns': const PdfNumber(2),
      });
      final data = Uint8List.fromList(<int>[2, 1, 2, 2, 1, 1]);
      expect(applyPredictor(data, parms), <int>[1, 2, 2, 3]);
    });

    test('image filters are reported as unsupported', () {
      final stream = PdfStream(
        PdfDict(<String, PdfObject>{'Filter': const PdfName('DCTDecode')}),
        Uint8List(0),
      );
      expect(
        () => decodeStreamData(stream),
        throwsA(isA<PdfUnsupportedFeatureException>()),
      );
    });
  });
}
